#  인용 = [@key] 또는 [@web:...]. 단독 저자 → 1인칭 금지. 결과 절에 해석 금지. 제목 쌍점 금지, 시리즈 제목 틀 반복 금지.
#  ★역방향(인플루엔자 예방접종률): 주모형 그대로 + 사후 검정(88r)은 결과를 본 뒤 추가했음을 Methods에 명시, 해석은 Discussion.
from numbers_pneu import load, ROB, REV, RS
import os, pandas as pd
N = load()
def tci(t): return f"MRR {t[0]:.3f}; 95% CrI {t[1]:.3f} to {t[2]:.3f}"
def ci(v): r = N["main"][v]; return tci((r["IRR"], r["lo"], r["hi"]))
M = N["main"]; T1 = N["T1"]
S43 = lambda a, v: N["s43"][(a, v)]
dW = lambda a: N["s43_waic"][a] - N["waic_main"]
NCO = lambda o, v: N["s41"][("H1_nco_" + o, v)]
S41 = lambda a, v: N["s41"][(a, v)]
S44 = lambda a, v: N["s44"][(a, v)]
S45 = lambda a, v: N["s45"][(a, v)]
SC = lambda s, v: N["sens_main"][s][v]
EN = {"강원도": "Gangwon", "충청남도": "South Chungcheong", "충청북도": "North Chungcheong", "경기도": "Gyeonggi", "서울시": "Seoul", "경상북도": "North Gyeongsang",
      "경상남도": "South Gyeongsang", "전라남도": "South Jeolla", "전라북도": "North Jeolla", "광주시": "Gwangju", "부산시": "Busan", "인천시": "Incheon", "울산시": "Ulsan",
      "대전시": "Daejeon", "세종시": "Sejong", "대구시": "Daegu", "제주도": "Jeju"}
def sidos(d, n):
    l = [f"{EN.get(k, k)} ({v})" for k, v in list(d.items())[:n]]; return ", ".join(l[:-1]) + " and " + l[-1]
KH = ("KH_typeI", "KH_typeII", "KH_typeIII", "KH_typeIV")
FLU, SMK, ALC, MDM, CHEW = "influenza_vaccination_rate", "current_smoking_rate", "high_risk_drinking_rate", "screening_suspected_diabetes_share", "chewing_discomfort_rate_65plus"
WALK, MPA, FAC = "walking_practice_rate", "moderate_pa_rate", "public_sports_facilities_per_100k"
OLD, BLS, LTC, EMS, FAC_LAND = "older_single_household_share", "basic_livelihood_rate", "ltc_hospitals_per_100k_65", "em_specialists_per_100k", "factory_land_share"
TITLE = "Against the global decline, late-life pneumonia mortality in Korea rose by 63% after age standardization"
assert ":" not in TITLE and "229" not in TITLE and len(TITLE.split()) <= 20 and not TITLE.startswith(("Do ", "Why", "Persistent", "Age-", "District", "Where"))
KEYWORDS = "Influenza vaccination; Living alone; Oldest old; Spatial epidemiology; Death certification"
assert 3 <= len(KEYWORDS.split(";")) <= 5 and not any(w.lower() in TITLE.lower() for k in KEYWORDS.split(";") for w in k.split()) and not any(w in KEYWORDS.lower().split() for w in ("and", "of"))
_LK = pd.read_csv(os.path.join(RS, "S1_likelihood.csv")); _LK = _LK[_LK.set == "REF_forced_only"].set_index("family").WAIC
_FAM = pd.read_csv(os.path.join(RS, "S3_main_fit.csv")).family.iloc[0]
assert _FAM == "nbinomial" and _LK["nbinomial"] < _LK["poisson"] and abs(_LK["nbinomial"] - N["waic_forced"]) < 0.5
N["waic_forced"] = float(_LK["nbinomial"])
NHYP = N["n_hyp"]; EXP_CHANCE = 0.05 * NHYP; assert NHYP == 13
SUP = {"methods": ("appendix", 1), "covariates": ("table", 1), "datacheck": ("table", 2), "specs": ("table", 3), "reverse": ("table", 4), "persistence": ("figure", 1), "regions": ("table", 5), "strobe": ("appendix", 2)}
def sup(k, short=False):
    kind, n = SUP[k]; lab = {"appendix": ("Supplemental Methods" if n == 1 else "Supplemental Appendix"), "table": f"Table S{n}", "figure": f"Figure S{n}"}[kind]
    return lab if short else f"{lab} in the Supplemental Material"
WN = ("W1_2011-15", "W2_2016-19", "W3_2020-24"); WY = ("2011-2015", "2016-2019", "2020-2024")
_W = pd.read_csv(os.path.join(RS, "S4_window_IRR.csv")).set_index(["cov", "window"])
def wt(v, w): r = _W.loc[(v, w)]; return (r.IRR, r.lo, r.hi, bool(r.cred))
RET = N["ret14"]; NALT = RET[FLU][1]
BEST = min(KH, key=lambda a: N["s43_waic"][a]); assert BEST == "KH_typeIV"
BW = lambda v, part: N["bw"][f"{v}__{part}"]   # 표준 이원 분해(88g bw_twoway, 부분집합 안정 4개 모두)
_hot = N["type_class"]["hotspot"]; _cold = N["type_class"]["coldspot"]; _nt = N["n_type"]
_NC = lambda v: tci((N["negctl"][v]["IRR"], N["negctl"][v]["lo"], N["negctl"][v]["hi"]))
VP = N["varpart"]; VSP = VP["spatial_structured"]["share_of_sum"]; VCOV = VP["fixed_covariates"]["share_of_sum"]
R4 = lambda v: S44("R4_single_" + v, v)

METHODS = [
("Design, outcome, and population",
 f"This ecological study used annual deaths from pneumonia (International Classification of Diseases, 10th revision, J12-J18) in 2011-2024 by district of residence from the national cause-of-death statistics of Statistics Korea, which cover all registered deaths [@web:kostat2026cause]. Data were extracted in November 2026. Districts were harmonized to {N['n_districts']} units with 2024 boundaries ({N['n_rows']:,} district-years), with resident populations by 5-year age group as denominators [@web:mois2026population] ({sup('methods')})."),
("Age standardization",
 "Expected deaths were obtained by indirect standardization: national age-specific pneumonia death rates in eighteen 5-year groups up to 85 years or older were applied to each district's age structure each year, and expected deaths were rescaled so that their national total equaled observed deaths [@inskip1983methods]. Observed over expected deaths gives the standardized mortality ratio (SMR). National trends were directly standardized to the 2015 population. Because the oldest group was open-ended, the share aged 80 years or older was also included as a forced control. Standardization in the principal analysis was by age, with the sex ratio as a forced control; a sensitivity analysis used expected deaths standardized by sex and age from national sex- and age-specific death rates."),
("District characteristics",
 f"Thirteen district characteristics were selected on the basis of the epidemiological literature on pneumonia death in older adults, covering prevention, host susceptibility, physical activity, social and structural conditions, care settings, and environment [@almirall2017risk; @torres2015individuals]. From the Community Health Survey (district age-standardized rates among adults aged 19 years or older [@kang2015korea]) came influenza vaccination in the past year, current smoking, high-risk drinking, walking practice, and moderate-or-higher-intensity physical activity, together with chewing difficulty among adults aged 65 years or older (a marker of oral and swallowing function). The national general health screening provided the share of attendees with suspected diabetes on fasting glucose, among those not already classified as under treatment. Structural and care characteristics were public sports facilities per 100,000 population, households of older adults living alone, the share of residents receiving basic livelihood security benefits (the national means-tested public assistance program), long-term care hospitals per 100,000 residents aged 65 years or older, emergency medicine specialists per 100,000 population, and the share of district area used as factory land as a proxy for industrial air pollution. Expected directions, data sources, observed years, and filled cells are listed in {sup('covariates')}, and panel checks before modeling in {sup('datacheck')}. Five controls were forced into every model: urban population share, physician density, sex ratio, fiscal autonomy, and the share aged 80 years or older. Covariates were standardized to 1 standard deviation, and missing years were filled within districts."),
("Statistical analysis",
 f"The likelihood was chosen by the lower widely applicable information criterion (WAIC) of the forced-controls model (negative binomial). Models had an offset of log expected deaths, a Besag-York-Mollié 2 (BYM2) district effect with penalized-complexity priors [@riebler2016intuitive; @simpson2017penalising], and random-walk and independent year effects, fitted by integrated nested Laplace approximation [@rue2009approximate] in R [@web:rcore2026]. Mortality rate ratios (MRRs) per 1 standard deviation are reported with 95% credible intervals (CrIs); an association was credible when the interval excluded 1. Intervals were not adjusted for multiplicity; with {NHYP} characteristics and independent null associations, about {EXP_CHANCE:.2f} would be expected to exclude 1 by chance, and the analysis is exploratory. Sensitivity to covariate selection was assessed with 200 random covariate subsets (subset-stable: interval excluding 1 in at least 75% of subsets containing the characteristic, same sign in at least 95%). Because subset fits share one model structure, structural checks were given priority: Knorr-Held type I-IV space-time interactions added unstructured or structured district-by-year terms, with types II and IV allowing each district its own time trend [@knorrheld2000bayesian], and a province-by-year effect absorbed regional shocks. Subset-stable characteristics were split into district means and two-way-centered within-district deviations [@bell2015explaining]. Fourteen alternative specifications, listed in {sup('specs')}, varied the likelihood, time effects, smoothing, lags, extreme values, survey averaging, and the years included. Further checks varied neighborhoods, priors, and age grouping, added a Spatial+-type adjustment [@dupont2022spatial], left out each province or year, perturbed filled values 20 times, added the share of deaths with ill-defined causes (R00-R99) as a marker of death certification and the out-of-district outpatient share as a marker of access, and refitted the principal model by window and to two comparison outcomes (people treated for stomach cancer and for infectious diseases). Hit-and-run accidents, a traffic culture index, and fires served as negative-control exposures, chosen as district characteristics without a plausible pathway to pneumonia death; E-values are reported in {sup('methods')}. Because annual Moran's I of raw ratios rises as deaths increase and Poisson noise falls, it was also computed on empirical Bayes-smoothed SMRs. Residual hot and cold spots had a posterior probability of a residual spatial rate ratio above 1 greater than 0.95 or less than 0.05; the variance of the linear predictor was partitioned into spatial, temporal, and covariate components."),
("Checks added after results were seen",
 f"Influenza vaccination was credible in the direction opposite to that expected. The principal model was kept, and post hoc checks fitted it with the forced controls alone and removed characteristics on the care and frailty, behavioral, and access pathways ({sup('reverse')})."),
("Ethics and reporting",
 f"The study used only published aggregate statistics. The institutional review board of the author's institution approved the study and its continuing review (details on the title page) and waived informed consent because no individual-level data were used. The study conforms to the principles of the Declaration of Helsinki and follows the STROBE statement [@vonelm2007strengthening] ({sup('strobe')}). Claude (Anthropic) and ChatGPT (OpenAI) were used only for translation and English-language editing of the manuscript; the author reviewed and edited all output and takes full responsibility for the content."),
]

_ME = N["moran_eb"]; _WT = N["win_hot_type"]; _wsh = lambda w: _WT[w]["county"] / sum(_WT[w].values())
_att = lambda a, v: 100 * __import__("math").log(S43(a, v)[0]) / __import__("math").log(M[v]["IRR"]) if a.startswith("KH") else 100 * __import__("math").log(S41(a, v)[0]) / __import__("math").log(M[v]["IRR"])
_PPC = float(__import__("decimal").Decimal(str(100 * N["ppc"]["coverage95"])).quantize(__import__("decimal").Decimal("0.1"), rounding="ROUND_HALF_UP"))
RESULTS = [
("Deaths, trends, and geography",
 f"Over 2011-2024, {N['cases_total']:,} pneumonia deaths occurred in {N['py']/1e6:.0f} million person-years; annual deaths rose from {N['cases_2011']:,} to {N['cases_2024']:,}, and the share of deaths at ages 85 years or older from {100*N['share85_2011']:.1f}% to {100*N['share85_2024']:.1f}% ({100*N['share75_2024']:.1f}% at 75 years or older in 2024) (Table 1). The directly age-standardized rate rose from {N['asr_2011']:.1f} per 100,000 in 2011 to a peak of {N['asr'][2018]:.1f} in 2018 and was {N['asr_2024']:.1f} in 2024 (ratio 2024 to 2011, {N['asr_ratio']:.2f}; range {min(N['asr'][t] for t in range(2019, 2025)):.1f}-{max(N['asr'][t] for t in range(2019, 2025)):.1f} in 2019-2024), whereas the crude rate rose from {N['crude_2011']:.1f} to {N['crude_2024']:.1f} (Figure 1). Moran's I was {N['moran_pooled']:.2f} for pooled log SMRs; annually it was {N['moran_y'][2011]:.2f} in 2011 and {N['moran_y'][2024]:.2f} in 2024 for raw ratios and {_ME[2011]:.2f} and {_ME[2024]:.2f} for empirical Bayes-smoothed ratios. The BYM2 spatial fraction was {N['phi'][0]:.2f} (95% CrI {N['phi'][1]:.2f} to {N['phi'][2]:.2f}). After adjustment, {N['n_hot']} districts were residual hot spots over the whole period, mainly in {sidos(N['hot_by_sido'], 6)}, with {N['hot_by_sido']['대구시']} urban wards each in Daegu and Gwangju; they comprised {_hot['county']} of {_nt['county']} counties, {_hot['city']} of {_nt['city']} cities, and {_hot['ward']} of {_nt['ward']} urban wards, and {N['hot_capital']} lay in the capital region. Cold spots numbered {N['n_cold']}, {N['cold_by_sido']['서울시']} in Seoul and {N['cold_by_sido']['경기도']} in Gyeonggi (Figure 1). In window-specific models, hot spots numbered {N['win_hot'][WN[0]]}, {N['win_hot'][WN[1]]}, and {N['win_hot'][WN[2]]}, of which counties made up {100*_wsh(WN[0]):.0f}%, {100*_wsh(WN[1]):.0f}%, and {100*_wsh(WN[2]):.0f}%; {N['hot_all_windows']} districts were hot spots in all three windows, and Kendall's W for annual district rankings was {N['kendall_W']:.2f} ({sup('persistence')}). Unadjusted smoothed SMRs correlated with the share of basic livelihood recipients (Spearman ρ {N['eb_bls']:.2f}) and with latitude (ρ {N['lat_eb']:.2f})."),
("District characteristics",
 f"Adding the {NHYP} characteristics changed WAIC from {N['waic_forced']:,.1f} to {N['waic_main']:,.1f}. Deaths were higher with more households of older adults living alone ({ci(OLD)}), more long-term care hospitals ({ci(LTC)}), more high-risk drinking ({ci(ALC)}), and higher influenza vaccination ({ci(FLU)}) (Table 2, Figure 2). Walking practice ({ci(WALK)}), moderate-or-higher physical activity ({ci(MPA)}), public sports facilities ({ci(FAC)}), current smoking ({ci(SMK)}), suspected diabetes, chewing difficulty, basic livelihood recipients ({ci(BLS)}), emergency medicine specialists, and factory land were not credibly associated. Of the three negative-control exposures, fires were credibly associated ({_NC('fires_per_10000')}); hit-and-run accidents and the traffic culture index were not. Of the summed variance components of the linear predictor, structured spatial variation accounted for {100*VSP:.1f}% and covariates for {100*VCOV:.1f}% ({100*VP['spatial_structured']['share_of_linear_predictor_var']:.1f}% and {100*VP['fixed_covariates']['share_of_linear_predictor_var']:.1f}% of the linear predictor variance, which includes covariances)."),
("Robustness",
 f"The four associations were subset-stable (credible in {100*N['mv'][LTC]['cred_frac']:.0f}% of subset fits for long-term care hospitals, {100*N['mv'][FLU]['cred_frac']:.0f}% for influenza vaccination, {100*N['mv'][OLD]['cred_frac']:.0f}% for older adults living alone, and {100*N['mv'][ALC]['cred_frac']:.0f}% for high-risk drinking) and remained credible with type I interactions, a Poisson-lognormal likelihood, and the added death-certification and access markers; the ill-defined cause share was itself associated with higher mortality ({tci(S45('Z1_illdefined', 'ill_defined_death_share'))}) ({sup('specs')}). When each district was allowed its own trend, the estimates moved toward 1 and their intervals included 1: in the type IV model, which had the lowest WAIC of the four interaction models (ΔWAIC {dW(BEST):,.0f}), the estimates were {tci(S43(BEST, OLD))} for older adults living alone, {tci(S43(BEST, LTC))} for long-term care hospitals, {tci(S43(BEST, ALC))} for high-risk drinking, and {tci(S43(BEST, FLU))} for influenza vaccination, retaining {_att(BEST, OLD):.0f}%, {_att(BEST, LTC):.0f}%, {_att(BEST, ALC):.0f}%, and {_att(BEST, FLU):.0f}% of the principal log rate ratios; type II and province-by-year models gave similar results ({tci(S41('C4_sido_year_iid', OLD))} for older adults living alone with province-by-year effects). None of the four was credible in the type III model, and basic livelihood recipients became credible in the type IV model ({tci(S43(BEST, BLS))}). With expected deaths standardized by sex and age, the four associations were unchanged ({tci(SC('ssx', OLD))} for older adults living alone). With ten age groups in the expected deaths, influenza vaccination and older adults living alone were no longer credible and basic livelihood recipients were credibly associated with lower mortality ({tci(SC('s8', BLS))}). With covariates lagged, walking practice was associated with lower mortality (1 year, {tci(S41('E1_lag1', WALK))}; 2 years, {tci(S41('E2_lag2', WALK))}) and suspected diabetes with higher mortality at 2 years ({tci(S41('E2_lag2', MDM))}); walking was also credible in 2016-2019 ({tci(wt(WALK, WN[1])[:3])}). Across the {NALT} alternative specifications, the associations were retained in {RET[FLU][0]} (influenza vaccination), {RET[LTC][0]} (long-term care hospitals), {RET[ALC][0]} (high-risk drinking), and {RET[OLD][0]} (older adults living alone). Older adults living alone ({tci(BW(OLD, 'between'))}) and high-risk drinking ({tci(BW(ALC, 'between'))}) were credible between districts, and long-term care hospitals within districts ({tci(BW(LTC, 'within'))}); the within-district interval for older adults living alone was wide ({tci(BW(OLD, 'within'))}). With filled values perturbed, older adults living alone was credible in {int(N['rubin'][OLD]['n_cred'])} of 20 fits (pooled {tci((N['rubin'][OLD]['IRR_pooled'], N['rubin'][OLD]['lo'], N['rubin'][OLD]['hi']))}). For the comparison outcomes, the four associations were not reproduced: high-risk drinking was credible in the opposite direction for stomach cancer care ({tci(NCO('GCA', ALC))}), and older adults living alone ({tci(NCO('INFECT', OLD))}) and high-risk drinking ({tci(NCO('INFECT', ALC))}) were credible in the opposite direction for infectious disease care; the others were not credible. Region-specific slopes lowered WAIC most for long-term care hospitals (ΔWAIC {N['s50_region_dwaic'][LTC]:.1f}; {tci(N['s50_region'][(LTC, 'Yeongnam')][:3])} in Yeongnam and {tci(N['s50_region'][(LTC, 'Chungcheong')][:3])} in Chungcheong) ({sup('regions')}). Residual Moran's I was {N['moran_resid']:.2f}, and posterior predictive 95% intervals covered {_PPC:.1f}% of district-years."),
("Influenza vaccination, opposite to the expected direction",
 f"The influenza vaccination association arose within districts ({tci(BW(FLU, 'within'))}) and not between districts ({tci(BW(FLU, 'between'))}). Window estimates were {tci(wt(FLU, WN[0])[:3])} in 2011-2015, {tci(wt(FLU, WN[1])[:3])} in 2016-2019, and {tci(wt(FLU, WN[2])[:3])} in 2020-2024; estimates were {tci(S41('E1_lag1', FLU))} with a 1-year lag and {tci(S41('E2_lag2', FLU))} with a 2-year lag. It was not credible for stomach cancer care ({tci(NCO('GCA', FLU))}) or infectious disease care ({tci(NCO('INFECT', FLU))}), nor when fitted with the forced controls alone ({tci(R4(FLU))}); it remained credible when the care and frailty ({tci(S44('R5_drop_care_frailty', FLU))}), behavioral ({tci(S44('R5_drop_behaviour', FLU))}), or access characteristics ({tci(S44('R5_drop_access', FLU))}) were removed ({sup('reverse')})."),
]

# 문장 주장 대조(결과표와 어긋나면 빌드 중단)
H = [v for v in M if M[v]["role"] == "hypothesis"]
assert N["n_cred_hyp"] == 4 and set(ROB) == {FLU, ALC, OLD, LTC} and N["waic_main"] < N["waic_forced"] and set(REV) == {FLU}
assert {v for v in H if M[v]["cred"]} == {FLU, ALC, OLD, LTC} and all(M[v]["IRR"] > 1 for v in ROB)
assert N["negctl"]["fires_per_10000"]["cred"] and not N["negctl"]["hit_and_run_rate"]["cred"] and not N["negctl"]["traffic_culture_index"]["cred"]
assert all(S43("KH_typeI", v)[3] for v in ROB) and not any(S43("KH_typeII", v)[3] or S43("KH_typeIV", v)[3] or S41("C4_sido_year_iid", v)[3] for v in ROB)
assert not any(S43("KH_typeIII", v)[3] for v in (OLD, FLU, ALC, LTC)) and S43(BEST, BLS)[3] and S43(BEST, BLS)[0] > 1
assert sorted(v for v in H if S43(BEST, v)[3]) == [BLS] and sorted(v for v in H if S43("KH_typeII", v)[3]) == []
assert all(S41("C1_poisson_lognormal", v)[3] for v in ROB) and all(S45("Z1_illdefined", v)[3] and S45("Z4_outside_care", v)[3] for v in ROB)
assert BW(OLD, "between")[3] and not BW(OLD, "within")[3] and BW(ALC, "between")[3] and not BW(ALC, "within")[3] and BW(LTC, "within")[3] and not BW(LTC, "between")[3]
assert BW(FLU, "within")[3] and not BW(FLU, "between")[3] and wt(FLU, WN[1])[3] and not wt(FLU, WN[0])[3] and not wt(FLU, WN[2])[3]
assert S41("E2_lag2", FLU)[3] and not S41("E1_lag1", FLU)[3] and not NCO("GCA", FLU)[3] and not NCO("INFECT", FLU)[3] and not R4(FLU)[3]
assert all(SC("ssx", v)[3] for v in ROB) and not any(SC("ssx", v)[3] for v in H if v not in ROB)
assert S41("E1_lag1", WALK)[3] and S41("E2_lag2", WALK)[3] and S41("E2_lag2", MDM)[3] and wt(WALK, WN[1])[3] and not SC("s8", FLU)[3] and not SC("s8", OLD)[3] and SC("s8", BLS)[3] and SC("s8", BLS)[0] < 1 and S45("Z1_illdefined", "ill_defined_death_share")[3]
assert _WT[WN[0]]["county"] / sum(_WT[WN[0]].values()) > _WT[WN[2]]["county"] / sum(_WT[WN[2]].values()) and _ME[2024] > _ME[2011] and N["hot_by_sido"]["대구시"] == N["hot_by_sido"]["광주시"] == 5
assert NCO("INFECT", OLD)[3] and NCO("INFECT", OLD)[0] < 1 and NCO("INFECT", ALC)[3] and NCO("INFECT", ALC)[0] < 1 and [v for v in ROB if NCO("GCA", v)[3]] == [ALC] and NCO("GCA", ALC)[0] < 1 and not NCO("INFECT", LTC)[3] and not NCO("INFECT", FLU)[3]
assert all(S44("R5_drop_" + a, FLU)[3] for a in ("care_frailty", "behaviour", "access"))
assert not any(M[v]["cred"] for v in (WALK, MPA, FAC, SMK, MDM, CHEW, BLS, EMS, FAC_LAND))
assert N["s50_region"][(LTC, "Yeongnam")][3] and N["s50_region"][(LTC, "Chungcheong")][3] and min(N["s50_region_dwaic"].values()) == N["s50_region_dwaic"][LTC]
assert N["moran_y"][2024] > N["moran_y"][2011] and N["asr_ratio"] > 1.5 and int(N["rubin"][OLD]["n_cred"]) == 12

if __name__ == "__main__":
    import re
    for h, t in METHODS + RESULTS: print("##", h, "\n", t, "\n")
    print("words M", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for _, t in METHODS), "R", sum(len(re.sub(r"\[@[^\]]+\]", "", t).split()) for _, t in RESULTS))
